#include "optimizer_loop_internal.h"

#include "ir_helpers.h"
#include "optimizer_helpers.h"

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Dispatch on a dynamic range direction once before the loop.
bool optimizer_loop_unswitch_range_direction(Ctx* ctx,
                                             IrFunctionId fid,
                                             IrBlockId pre,
                                             IrBlockId head_id) {
  IrFunction* fn = &ctx->ir.functions.data[fid];
  IrBlock* head = &fn->blocks.data[head_id];
  if (head->instructions.count != 1 ||
      head->instructions.data[0].type != IR_INST_LOAD ||
      head->terminator.type != IR_TERMINATOR_CONDITIONAL)
    return false;

  IrBlockTerminator direction = head->terminator;
  IrBlockId up = direction.value.conditional_target.true_target;
  IrBlockId down = direction.value.conditional_target.false_target;
  if (up == down || up == pre || down == pre || up == head_id ||
      down == head_id || optimizer_loop_edge_count(fn, up) != 1 ||
      optimizer_loop_edge_count(fn, down) != 1)
    return false;

  const IrBlock* up_test = &fn->blocks.data[up];
  const IrBlock* down_test = &fn->blocks.data[down];
  if (up_test->instructions.count != 1 || down_test->instructions.count != 1 ||
      up_test->terminator.type != IR_TERMINATOR_CONDITIONAL ||
      down_test->terminator.type != IR_TERMINATOR_CONDITIONAL)
    return false;

  IrInstruction up_cmp = up_test->instructions.data[0];
  IrInstruction down_cmp = down_test->instructions.data[0];
  IrValueId induction = head->instructions.data[0].result;
  if ((up_cmp.type != IR_INST_LT && up_cmp.type != IR_INST_LE) ||
      (down_cmp.type != IR_INST_GT && down_cmp.type != IR_INST_GE) ||
      !optimizer_loop_direct_use(up_cmp.operands.binary.left, induction) ||
      !optimizer_loop_direct_use(down_cmp.operands.binary.left, induction) ||
      !optimizer_loop_direct_use(
          up_test->terminator.value.conditional_target.condition,
          up_cmp.result) ||
      !optimizer_loop_direct_use(
          down_test->terminator.value.conditional_target.condition,
          down_cmp.result))
    return false;

  IrBlockId body_id = up_test->terminator.value.conditional_target.true_target;
  IrBlockId exit = up_test->terminator.value.conditional_target.false_target;
  if (body_id == pre || body_id == head_id || body_id == up ||
      body_id == down || exit == body_id || exit == pre || exit == head_id ||
      exit == up || exit == down ||
      body_id != down_test->terminator.value.conditional_target.true_target ||
      exit != down_test->terminator.value.conditional_target.false_target ||
      optimizer_loop_edge_count(fn, body_id) != 2)
    return false;

  const IrBlock* body = &fn->blocks.data[body_id];
  if (body->instructions.count > 8 ||
      body->terminator.type != IR_TERMINATOR_JUMP)
    return false;

  IrBlockId latch = body->terminator.value.jump_target;
  if (latch == pre || latch == head_id || latch == up || latch == down ||
      latch == body_id || latch == exit ||
      optimizer_loop_edge_count(fn, latch) != 1 ||
      fn->blocks.data[latch].instructions.count != 2 ||
      !optimizer_loop_jumps_to(&fn->blocks.data[latch], head_id))
    return false;

  RangeBody region = {.blocks = {head_id, down, body_id, latch},
                      .count = 4,
                      .latch = IR_INVALID_ID};
  size_t* uses = ctx->optimizer.value_data;
  optimizer_count_value_uses(fn, uses);
  for (size_t b = 0; b < region.count; b++) {
    const IrInstructionArray* instructions =
        &fn->blocks.data[region.blocks[b]].instructions;
    for (size_t i = 0; i < instructions->count; i++) {
      IrValueId result = instructions->data[i].result;

      if (result == IR_INVALID_ID)
        continue;

      size_t local = optimizer_loop_region_uses(fn, &region, result) +
                     optimizer_loop_instruction_uses(&up_cmp, result);

      if (local != uses[result] ||
          optimizer_loop_direct_use(
              direction.value.conditional_target.condition, result))
        return false;
    }
  }

  if (uses[up_cmp.result] != 1 ||
      optimizer_loop_direct_use(direction.value.conditional_target.condition,
                                up_cmp.result))
    return false;

  // Clone one loop direction so the sign test only runs on entry.
  IrBlockId first = fn->blocks.count;
  for (size_t b = 0; b < region.count; b++)
    ir_add_block(ctx, fid);

  size_t offset = fn->value_count;
  for (size_t b = 0; b < region.count; b++) {
    IrBlockId new_id = first + b;
    IrBlockId old_id = region.blocks[b];

    optimizer_loop_clone_iteration_block(
        ctx, fid, new_id, old_id, &region, IR_INVALID_ID, IR_INVALID_ID,
        (IrOperand){.type = IR_OP_UNIT}, offset);

    IrBlockTerminator term = fn->blocks.data[old_id].terminator;

    if (old_id == head_id) {
      term = (IrBlockTerminator){.type = IR_TERMINATOR_JUMP,
                                 .value.jump_target = first + 1};
    } else if (old_id == down) {
      term.value.conditional_target.true_target = first + 2;
      term.value.conditional_target.condition.value.id += offset;
    } else {
      term.value.jump_target =
          first + optimizer_loop_region_index(&region, term.value.jump_target);
    }

    ir_set_terminator(ctx, fid, new_id, term);
  }

  fn->value_count = offset * 2;

  direction.value.conditional_target.true_target = head_id;
  direction.value.conditional_target.false_target = first;

  ir_set_terminator(ctx, fid, pre, direction);
  ir_set_terminator(
      ctx, fid, head_id,
      (IrBlockTerminator){.type = IR_TERMINATOR_JUMP, .value.jump_target = up});

  return true;
}
